// Reads one square of a printed chess diagram with a small convolutional network.
//
// A plain forward pass with no runtime dependency, so the coach's browser and the
// API's Jest suite run the very same code, like the rest of the recognizer. The
// weights are generated by scripts/diagram-import/train-square-classifier.py.
//
// Layers: 3 × (3×3 convolution, ReLU, 2×2 max pool), then two dense layers.

import { DIAGRAM_SQUARE_MODEL, type DiagramModelTensor } from "./diagram-square-model";

const SIZE = DIAGRAM_SQUARE_MODEL.size;

export type SquareReading = {
  /** The most likely piece as a FEN letter, or null for an empty square. */
  piece: string | null;
  probability: number;
  /** The runner-up, or null when that is an empty square. */
  alternative: string | null;
  alternativeProbability: number;
};

type Conv = { weights: Float32Array; bias: Float32Array; inputs: number; outputs: number };
type Dense = { weights: Float32Array; bias: Float32Array; inputs: number; outputs: number };
type Network = { convs: Conv[]; dense: Dense[] };

let network: Network | null = null;

function decodeWeights(tensor: DiagramModelTensor): Float32Array {
  const bytes = decodeBase64(tensor.data);
  const out = new Float32Array(bytes.length);
  for (let i = 0; i < bytes.length; i += 1) out[i] = ((bytes[i] << 24) >> 24) * tensor.scale;
  return out;
}

/** atob isn't in every runtime this package reaches, and Buffer isn't in the browser. */
function decodeBase64(text: string): Uint8Array {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const trimmed = text.replace(/=+$/, "");
  const out = new Uint8Array(Math.floor((trimmed.length * 3) / 4));
  let bits = 0;
  let value = 0;
  let index = 0;
  for (let i = 0; i < trimmed.length; i += 1) {
    value = (value << 6) | alphabet.indexOf(trimmed[i]);
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out[index] = (value >> bits) & 255;
      index += 1;
    }
  }
  return out;
}

function load(): Network {
  if (network) return network;
  const { convs, dense } = DIAGRAM_SQUARE_MODEL;
  network = {
    convs: convs.map((layer) => ({
      bias: Float32Array.from(layer.bias),
      inputs: layer.inputs,
      outputs: layer.outputs,
      weights: decodeWeights(layer.weights),
    })),
    dense: dense.map((layer) => ({
      bias: Float32Array.from(layer.bias),
      inputs: layer.inputs,
      outputs: layer.outputs,
      weights: decodeWeights(layer.weights),
    })),
  };
  return network;
}

function convRelu(input: Float32Array, side: number, layer: Conv): Float32Array {
  const { inputs, outputs, weights, bias } = layer;
  const output = new Float32Array(outputs * side * side);
  for (let o = 0; o < outputs; o += 1) {
    const outStart = o * side * side;
    for (let i = 0; i < inputs; i += 1) {
      const inStart = i * side * side;
      const kernel = (o * inputs + i) * 9;
      for (let ky = -1; ky <= 1; ky += 1) {
        for (let kx = -1; kx <= 1; kx += 1) {
          const weight = weights[kernel + (ky + 1) * 3 + (kx + 1)];
          if (weight === 0) continue;
          const y0 = Math.max(0, -ky);
          const y1 = Math.min(side, side - ky);
          const x0 = Math.max(0, -kx);
          const x1 = Math.min(side, side - kx);
          for (let y = y0; y < y1; y += 1) {
            const to = outStart + y * side;
            const from = inStart + (y + ky) * side + kx;
            for (let x = x0; x < x1; x += 1) output[to + x] += weight * input[from + x];
          }
        }
      }
    }
    for (let p = 0; p < side * side; p += 1) {
      const v = output[outStart + p] + bias[o];
      output[outStart + p] = v > 0 ? v : 0;
    }
  }
  return output;
}

function maxPool(input: Float32Array, channels: number, side: number): Float32Array {
  const half = side >> 1;
  const output = new Float32Array(channels * half * half);
  for (let c = 0; c < channels; c += 1) {
    const from = c * side * side;
    const to = c * half * half;
    for (let y = 0; y < half; y += 1) {
      for (let x = 0; x < half; x += 1) {
        const a = from + 2 * y * side + 2 * x;
        output[to + y * half + x] = Math.max(input[a], input[a + 1], input[a + side], input[a + side + 1]);
      }
    }
  }
  return output;
}

function denseLayer(input: Float32Array, layer: Dense, relu: boolean): Float32Array {
  const output = new Float32Array(layer.outputs);
  for (let o = 0; o < layer.outputs; o += 1) {
    let sum = layer.bias[o];
    const row = o * layer.inputs;
    for (let i = 0; i < layer.inputs; i += 1) sum += layer.weights[row + i] * input[i];
    output[o] = relu && sum < 0 ? 0 : sum;
  }
  return output;
}

/** Class probabilities (order: DIAGRAM_SQUARE_MODEL.classes) for one sampled patch. */
export function diagramSquareProbabilities(patch: Float32Array): Float32Array {
  const { convs, dense } = load();
  let x: Float32Array = new Float32Array(patch.length);
  for (let i = 0; i < patch.length; i += 1) x[i] = (patch[i] - 0.5) * 2;
  let side = SIZE;
  for (const layer of convs) {
    x = maxPool(convRelu(x, side, layer), layer.outputs, side);
    side >>= 1;
  }
  const logits = denseLayer(denseLayer(x, dense[0], true), dense[1], false);
  let top = -Infinity;
  for (const v of logits) if (v > top) top = v;
  let total = 0;
  const out = new Float32Array(logits.length);
  for (let i = 0; i < logits.length; i += 1) {
    out[i] = Math.exp(logits[i] - top);
    total += out[i];
  }
  for (let i = 0; i < out.length; i += 1) out[i] /= total;
  return out;
}

const pieceOf = (classIndex: number) => (classIndex === 0 ? null : DIAGRAM_SQUARE_MODEL.classes[classIndex]);

export function readDiagramSquare(patch: Float32Array): SquareReading {
  const probabilities = diagramSquareProbabilities(patch);
  let best = 0;
  let second = -1;
  for (let i = 1; i < probabilities.length; i += 1) {
    if (probabilities[i] > probabilities[best]) {
      second = best;
      best = i;
    } else if (second < 0 || probabilities[i] > probabilities[second]) {
      second = i;
    }
  }
  return {
    alternative: pieceOf(second),
    alternativeProbability: probabilities[second],
    piece: pieceOf(best),
    probability: probabilities[best],
  };
}
